trait Shape { fn area(&self) -> f64; }
struct Sq { s: f64 }
impl Shape for Sq { fn area(&self) -> f64 { self.s * self.s } }
struct Ci { r: f64 }
impl Shape for Ci { fn area(&self) -> f64 { 3.0 * self.r * self.r } }
fn main() {
    let shapes: Vec<Box<dyn Shape>> = vec![Box::new(Sq { s: 2.0 }), Box::new(Ci { r: 1.0 })];
    let total: f64 = shapes.iter().map(|s| s.area()).sum();
    println!("{:.1}", total);
}

